// ─── helpers ───────────────────────────────────────────────
const slugify = s =>
  s.toLowerCase()
   .replace(/[^a-z0-9\s-]/g, '')
   .trim()
   .replace(/\s+/g, '-')
   .slice(0, 80);

function guessCategory(text) {
  const t = text.toLowerCase();
  if (/agent|mcp|orchestrat|workflow|harness/.test(t)) return 7;
  if (/security|sast|vuln|pentest|guardrail/.test(t)) return 8;
  if (/test|eval|benchmark/.test(t))                  return 6;
  if (/frontend|ui\b|react|vue|tailwind|component/.test(t)) return 4;
  if (/api|framework|sdk|inference|serving/.test(t))  return 3;
  if (/code|copilot|editor|ide|autocomplete/.test(t)) return 2;
  return 5; // backend & infra
}

// ─── fetch sources in parallel ──────────────────────────────
const GITHUB_TOKEN = ($env['GITHUB_TOKEN'] ?? '').trim();
const ghHeaders = {
  Accept: 'application/vnd.github.v3+json',
  'X-GitHub-Api-Version': '2022-11-28',
  ...(GITHUB_TOKEN ? { Authorization: `Bearer ${GITHUB_TOKEN}` } : {}),
};

const [ghRes, hfRes] = await Promise.allSettled([
  fetch(
    'https://api.github.com/search/repositories?q=topic:ai+topic:llm+stars:>200+pushed:>2026-01-01&sort=stars&order=desc&per_page=20',
    { headers: ghHeaders }
  ).then(r => r.json()),

  fetch(
    'https://huggingface.co/api/models?sort=trending&limit=20&filter=text-generation'
  ).then(r => r.json()),
]);

// ─── normalize ──────────────────────────────────────────────
const tools = [];
const seen  = new Set();

// GitHub repos → tools
if (ghRes.status === 'fulfilled' && Array.isArray(ghRes.value?.items)) {
  for (const repo of ghRes.value.items) {
    const slug = slugify(repo.name);
    if (!slug || seen.has(slug)) continue;
    seen.add(slug);
    const desc = (repo.description || repo.name).slice(0, 500);
    tools.push({
      name:          repo.name,
      slug,
      description:   desc,
      website_url:   repo.html_url,
      category_id:   guessCategory([repo.full_name, desc, ...(repo.topics ?? [])].join(' ')),
      is_open_source: true,
      has_api:        false,
      has_free_tier:  true,
      pricing_model: 'open-source',
      stars_github:  repo.stargazers_count,
      is_new_today:  true,
    });
  }
}

// HuggingFace models → tools
if (hfRes.status === 'fulfilled' && Array.isArray(hfRes.value)) {
  for (const model of hfRes.value) {
    const rawId = (model.modelId || model.id || '').trim();
    const slug  = slugify(rawId.replace(/\//g, '-'));
    if (!slug || seen.has(slug)) continue;
    seen.add(slug);
    tools.push({
      name:          rawId,
      slug,
      description:   `Trending open model on HuggingFace. Downloads: ${(model.downloads ?? 0).toLocaleString()}, Likes: ${model.likes ?? 0}.`,
      website_url:   `https://huggingface.co/${rawId}`,
      category_id:   3,
      is_open_source: true,
      has_api:        true,
      has_free_tier:  true,
      pricing_model: 'open-source',
      stars_github:  null,
      is_new_today:  true,
    });
  }
}

return [{ json: { tools, topics: [] } }];

const result = $input.first().json;
console.log('[AI Landscape Pipeline]', JSON.stringify(result));
return [{ json: { success: true, ...result, ran_at: new Date().toISOString() } }];
